 write(*,FMT= "(A1,A,t21,F6.2,A)",ADVANCE="NO") achar(13), &        !achar(13) = CR ’\r’ (carriage ret)
     & " Percent Complete: ", (real(current)/real(total))*100.0,"%"
END subroutine progress

