    seg(i)%voiso  = i
    seg(i)%voise  = i
    seg(i)%vnno   = i
    seg(i)%vnne   = i
    seg(i)%surface      = izero
    seg(i)%gd           = izero
    seg(i)%VarFreePlan  = izero !this segment will be eliminated
    out(i)  = .true.

    if (seg(i1e)%vnne == NSEGMAX) then

      ii=i1e
      counter = IZERO
      do while (ii /= NSEGMAX)
