      VecE(1:3) = real(Ei1o(:)-Intersec(:),DP)
      ii=-IUN
      do while (dot_product(VecE(1:3),Plane_millerR(1:3,j)) >= IZERO)
        ii=ii+IUN
        if (ii > 10000) then
