      seg(i1e)%surface = IUN
      seg(i1e)%VarFreePlan = seg(i)%VarFreePlan
      singulier(i1e) = .True.
      seg(i1e)%vnno = NSEGMAX

      Oi1e=seg(i1e)%O

      Intersec(1:3) =InterPlanSeg(Plane_millerR(1:3,j),Plane_pos(j),Real(Oi1e,DP),BVECLIN(:,VLI))
      VecO(1:3) = real(Oi1e(:)-Intersec(:),DP)
      ii=-IUN
